        // MARK: - Help center, unified errors, accessibility
        "help.title": [.zhHans: "帮助中心", .en: "Help Center"],
        "help.subtitle": [
            .zhHans: "首次配置、更新、日志、多账号、密钥与隐私。可打开日志、诊断中心、Release 页面和本地用户手册。",
            .en: "First setup, updates, logs, accounts, keys, and privacy. Open logs, Diagnostics, the Release page, or the local user guide.",
        ],
        "help.section.actions": [.zhHans: "快捷入口", .en: "Shortcuts"],
        "help.section.topics": [.zhHans: "主题与 FAQ", .en: "Topics and FAQ"],
        "help.open_logs": [.zhHans: "打开日志", .en: "Open logs"],
        "help.open_diagnostics": [.zhHans: "打开诊断中心", .en: "Open Diagnostics"],
        "help.open_releases": [.zhHans: "打开 Release 页面", .en: "Open Release page"],
        "help.open_guide": [.zhHans: "打开用户手册", .en: "Open user guide"],
        "settings.help": [.zhHans: "帮助中心", .en: "Help Center"],
        "settings.help_sub": [.zhHans: "首次配置、日志、隐私和常见问题", .en: "First setup, logs, privacy, and FAQ"],
        "help.topic.first_setup.title": [.zhHans: "首次配置", .en: "First setup"],
        "help.topic.first_setup.body": [
            .zhHans: "首次打开会看到引导：说明本机优先、检查兼容性、选择第一个会员并做一次检测。可随时跳过；设置里仍有「继续引导」。关闭引导窗口不会退出智额。",
            .en: "The first launch walks through local-first privacy, compatibility, choosing a membership, and one check. Skip anytime; Settings keeps Continue setup. Closing the guide does not quit SmartQuota.",
        ],
        "help.topic.check_updates.title": [.zhHans: "检查更新", .en: "Check for updates"],
        "help.topic.check_updates.body": [
            .zhHans: "在设置中点「检查更新」，会显示当前版本、新版本、日期、说明、安装包大小和最低 macOS。确认后才下载。优先 PKG，没有 PKG 时打开 DMG。缺少资产或校验时可打开 Release 页。默认 ad-hoc 签名，首次打开请右键打开。不会静默自动更新。",
            .en: "Tap Check for Updates in Settings to see the current version, new version, date, notes, installer size, and minimum macOS. Download starts only after you confirm. PKG is preferred; DMG is the fallback. If assets or checksums are missing, you can open the Release page. Default signing is ad-hoc — Control-click to open the first time. There is no silent auto-update.",
        ],
        "help.topic.log_location.title": [.zhHans: "日志位置", .en: "Log location"],
        "help.topic.log_location.body": [
            .zhHans: "日志在 ~/Library/Logs/SmartQuota/SmartQuota.log，只留在本机。设置或帮助中心可打开该文件。请勿分享含有邮箱、密钥或 Cookie 的原始日志。",
            .en: "Logs live at ~/Library/Logs/SmartQuota/SmartQuota.log on this Mac. Settings or Help can open the file. Do not share raw logs that contain emails, keys, or cookies.",
        ],
        "help.topic.multi_account.title": [.zhHans: "多账号", .en: "Multiple accounts"],
        "help.topic.multi_account.body": [
            .zhHans: "同一会员可跟踪多个账号，但同一时间只刷新本机当前登录。读不到登录态时保留上次快照并显示「未登录」；网络失败显示「连接失败」，两者不会混淆。",
            .en: "A membership can track several accounts, but only the account signed in on this Mac is refreshed. If login is missing, the last snapshot stays and shows Not signed in. Network failures show Connection failed and are not mixed with that state.",
        ],
        "help.topic.key_security.title": [.zhHans: "密钥安全", .en: "Key security"],
        "help.topic.key_security.body": [
            .zhHans: "API Key、Token 和 Cookie 保存在本机钥匙串，不会进入导出、备份或诊断摘要。可在设置 › 安全中用 Touch ID 保护查看。删除账号只清理智额本地记录，不会登出外部 CLI。",
            .en: "API keys, tokens, and cookies stay in the local Keychain and never enter export, backup, or diagnostic summaries. Touch ID can protect viewing them in Settings › Security. Deleting an account only clears SmartQuota’s local record.",
        ],
        "help.topic.privacy.title": [.zhHans: "隐私", .en: "Privacy"],
        "help.topic.privacy.body": [
            .zhHans: "智额是本机优先：设置、备注、缓存和诊断都留在这台 Mac。没有云账号，也不会上传密钥、Cookie、完整邮箱、原始日志或额度明细。",
            .en: "SmartQuota is local-first: settings, notes, cache, and diagnostics stay on this Mac. There is no cloud account, and keys, cookies, full emails, raw logs, and quota details are not uploaded.",
        ],
        "help.topic.faq.title": [.zhHans: "常见问题", .en: "FAQ"],
        "help.topic.faq.body": [
            .zhHans: "Q：卡片显示未登录或连接失败？\nA：未登录会保留旧快照；连接失败也保留旧数据。下一步：打开配置或诊断中心，不要删除会员重来。\n\nQ：关掉面板后图标没了？\nA：点关闭只收起面板，不会退出。只有「退出应用」才结束进程。\n\nQ：如何自己排查？\nA：打开诊断中心运行检查，或查看本机日志和用户手册。",
            .en: "Q: The card says Not signed in or Connection failed?\nA: Both keep the old snapshot. Next: open setup or Diagnostics; do not delete the membership to start over.\n\nQ: The menu-bar icon vanished after closing the panel?\nA: Close only hides the panel. Only Quit App ends the process.\n\nQ: How do I troubleshoot?\nA: Run Diagnostics, or open the local log and user guide.",
        ],
        "error.refreshNetwork.what": [.zhHans: "刷新失败：网络不可用或请求超时。", .en: "Refresh failed: the network is unavailable or the request timed out."],
        "error.refreshNetwork.kept": [.zhHans: "已保留该会员上次成功读取的额度快照，没有清空历史数据。", .en: "The last successful quota snapshot is kept. Historical data was not cleared."],
        "error.refreshNetwork.next": [.zhHans: "请恢复网络后点刷新，或打开诊断中心查看网络检查。", .en: "Restore the network and tap Refresh, or open Diagnostics to inspect reachability."],
        "error.refreshNotLoggedIn.what": [.zhHans: "当前本机没有可用登录态，因此读不到新额度。", .en: "This Mac has no usable sign-in, so new quota data could not be read."],
        "error.refreshNotLoggedIn.kept": [.zhHans: "已保留上次成功快照，并显示「未登录」，不会用空数据覆盖。", .en: "The last successful snapshot is kept and shown as Not signed in. It is not replaced with empty data."],
        "error.refreshNotLoggedIn.next": [.zhHans: "请在对应 CLI 或客户端重新登录，然后在设置中检测配置。", .en: "Sign in again in the matching CLI or app, then test the setup in Settings."],
        "error.refreshMissingCLI.what": [.zhHans: "未找到该会员需要的命令行工具，无法检测额度。", .en: "The command-line tool this membership needs was not found, so quota could not be checked."],
        "error.refreshMissingCLI.kept": [.zhHans: "已保留旧快照；智额不会卸载或改写你已有的配置。", .en: "The previous snapshot is kept. SmartQuota does not uninstall tools or rewrite your existing config."],
        "error.refreshMissingCLI.next": [.zhHans: "请自行安装并登录对应 CLI。智额不会自动安装第三方工具。可打开帮助或诊断查看说明。", .en: "Install and sign in to that CLI yourself. SmartQuota will not auto-install third-party tools. Open Help or Diagnostics for the steps."],
        "error.refreshMissingKey.what": [.zhHans: "缺少本机密钥或凭证，无法完成检测。", .en: "A local key or credential is missing, so the check could not finish."],
        "error.refreshMissingKey.kept": [.zhHans: "已保留旧数据；不会把空密钥写入钥匙串，也不会删除其他账号。", .en: "Previous data is kept. An empty key is not written to the Keychain, and other accounts are not deleted."],
        "error.refreshMissingKey.next": [.zhHans: "到设置 › 额度检测配置中补上 Key，或打开诊断中心查看「缺少 Key」。", .en: "Add the key in Settings › Quota detection, or open Diagnostics and look for Missing key."],
        "error.refreshServiceRejected.what": [.zhHans: "会员服务拒绝了这次请求（限流或接口错误）。", .en: "The membership service rejected this request (rate limit or endpoint error)."],
        "error.refreshServiceRejected.kept": [.zhHans: "已保留上次有效额度；这次失败不会改写本地缓存为空白。", .en: "The last valid quota is kept. This failure does not blank the local cache."],
        "error.refreshServiceRejected.next": [.zhHans: "稍后再刷新，或打开会员后台确认套餐与登录。也可运行诊断。", .en: "Refresh later, or open the membership dashboard to confirm the plan and sign-in. You can also run Diagnostics."],
        "error.refreshFailed.what": [.zhHans: "这次刷新没有得到新的额度结果。", .en: "This refresh did not return a new quota result."],
        "error.refreshFailed.kept": [.zhHans: "已保留旧快照和账号记录，不会因为一次失败清空会员。", .en: "The previous snapshot and account record are kept. One failure does not remove the membership."],
        "error.refreshFailed.next": [.zhHans: "请打开诊断中心或日志查看原因，再重试刷新。", .en: "Open Diagnostics or the log to see why, then try Refresh again."],
        "error.updateCheckFailed.what": [.zhHans: "检查更新失败，没有下载或安装任何新版本。", .en: "The update check failed. No new version was downloaded or installed."],
        "error.updateCheckFailed.kept": [.zhHans: "当前已安装版本保持不变。", .en: "The installed version is unchanged."],
        "error.updateCheckFailed.next": [.zhHans: "请检查网络后重试，或打开项目 Release 页面手动下载。", .en: "Check the network and try again, or open the project Release page to download manually."],
        "error.settingsSaveFailed.what": [.zhHans: "设置没有写成功。", .en: "Settings could not be saved."],
        "error.settingsSaveFailed.kept": [.zhHans: "磁盘上的原设置文件保持不变。", .en: "The settings file on disk is left unchanged."],
        "error.settingsSaveFailed.next": [.zhHans: "请确认 ~/.smartquota 可写，然后重试。必要时打开诊断或安全模式。", .en: "Confirm ~/.smartquota is writable, then retry. Open Diagnostics or Safe Mode if it keeps failing."],
        "error.backupRestoreFailed.what": [.zhHans: "恢复备份没有完成。", .en: "Restoring the backup did not finish."],
        "error.backupRestoreFailed.kept": [.zhHans: "当前设置和备份文件都还在，已保留原数据，没有用半成品覆盖。", .en: "Current settings and the backup file are still in place. Previous data is kept and was not half-overwritten."],
        "error.backupRestoreFailed.next": [.zhHans: "请再试一次，或打开日志查看备份位置。", .en: "Try again, or open the log to find the backup location."],
        "error.exportFailed.what": [.zhHans: "导出非敏感设置失败。", .en: "Exporting non-sensitive settings failed."],
        "error.exportFailed.kept": [.zhHans: "本机设置、密钥和备份均未改动。", .en: "Local settings, keys, and backups were not changed."],
        "error.exportFailed.next": [.zhHans: "请另选可写位置再导出。导出文件不会包含密钥。", .en: "Choose a writable location and export again. The file never includes secrets."],
        "error.importFailed.what": [.zhHans: "导入设置没有完成。", .en: "Importing settings did not finish."],
        "error.importFailed.kept": [.zhHans: "当前设置、钥匙串和外部登录态均未改动。", .en: "Current settings, Keychain items, and external logins were left unchanged."],
        "error.importFailed.next": [.zhHans: "请检查文件是否为智额导出的 JSON，再选择合并或覆盖。", .en: "Check that the file is a SmartQuota export, then choose merge or overwrite."],
        "error.migrationFailed.what": [.zhHans: "设置迁移失败，没有采用不完整的新配置。", .en: "Settings migration failed. An incomplete new configuration was not applied."],
        "error.migrationFailed.kept": [.zhHans: "原 settings.json 已恢复或从未改写，并保留迁移前备份。", .en: "The original settings.json was restored or never rewritten. The pre-migration backup is kept."],
        "error.migrationFailed.next": [.zhHans: "在安全模式中恢复备份或查看备份路径，然后重试正常模式。", .en: "In Safe Mode, restore a backup or note the backup path, then retry normal mode."],
        "error.settingsCorrupt.what": [.zhHans: "settings.json 无法读取。", .en: "settings.json could not be read."],
        "error.settingsCorrupt.kept": [.zhHans: "损坏文件仍留在原处，并复制了一份到 recovery/corrupt/。当前只用只读默认值。", .en: "The damaged file is still in place, with a copy under recovery/corrupt/. Only read-only defaults are in use."],
        "error.settingsCorrupt.next": [.zhHans: "打开安全模式恢复备份，或导出后重置智额自己的设置。", .en: "Open Safe Mode to restore a backup, or export and then reset SmartQuota’s own settings."],
        "a11y.refresh.label": [.zhHans: "刷新全部会员", .en: "Refresh all memberships"],
        "a11y.refresh.hint": [.zhHans: "重新检测已开启会员的额度。可按 ⌘R。", .en: "Recheck quota for enabled memberships. Press ⌘R."],
        "a11y.refresh.value.idle": [.zhHans: "空闲", .en: "Idle"],
        "a11y.refresh.value.running": [.zhHans: "正在刷新", .en: "Refreshing"],
        "a11y.pin.label": [.zhHans: "固定窗口", .en: "Pin window"],
        "a11y.pin.hint": [.zhHans: "打开或关闭常驻窗口，点击其他应用时面板不会消失。", .en: "Open or close the persistent window so the panel stays when you click another app."],
        "a11y.pin.value.on": [.zhHans: "已固定", .en: "Pinned"],
        "a11y.pin.value.off": [.zhHans: "未固定", .en: "Unpinned"],
        "a11y.close_panel.label": [.zhHans: "关闭面板", .en: "Close panel"],
        "a11y.close_panel.hint": [.zhHans: "只隐藏窗口，智额继续在菜单栏运行。", .en: "Hides the window only. SmartQuota stays in the menu bar."],
        "a11y.close_panel.value": [.zhHans: "面板打开", .en: "Panel open"],
        "a11y.settings_icon.label": [.zhHans: "设置", .en: "Settings"],
        "a11y.settings_icon.hint": [.zhHans: "打开设置。可按 ⌘,。", .en: "Open Settings. Press ⌘,."],
        "a11y.settings_icon.value": [.zhHans: "设置", .en: "Settings"],
        "a11y.share.label": [.zhHans: "分享 Claude 通行", .en: "Share Claude pass"],
        "a11y.share.hint": [.zhHans: "显示可分享的 Claude 访客通行。", .en: "Show a shareable Claude guest pass."],
        "a11y.share.value": [.zhHans: "可分享", .en: "Available"],
        "a11y.help.label": [.zhHans: "帮助中心", .en: "Help Center"],
        "a11y.help.hint": [.zhHans: "打开应用内帮助、日志和用户手册。可按 ⌘?。", .en: "Open in-app help, logs, and the user guide. Press ⌘?."],
        "a11y.help.value": [.zhHans: "帮助", .en: "Help"],
        "a11y.back.label": [.zhHans: "返回", .en: "Back"],
        "a11y.back.hint": [.zhHans: "返回菜单栏主面板。", .en: "Return to the menu-bar panel."],
        "a11y.back.value": [.zhHans: "设置已打开", .en: "Settings open"],
        "a11y.account_delete.hint": [.zhHans: "删除后只清理智额本地记录，不会登出外部 CLI。可按键盘确认或取消。", .en: "Deletes only SmartQuota’s local record, not the external CLI login. Confirm or cancel with the keyboard."],
